INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('futebol-051', 'en', 'Who or what is it?', 'Pelé: He was born in Três Corações. He played for Santos and the New York Cosmos. He won the World Cup in 1958, 1962 and 1970. His birth name was Edson Arantes do Nascimento.', NULL, '["He was born in Três Corações.","He played for Santos and the New York Cosmos.","He won the World Cup in 1958, 1962 and 1970.","His birth name was Edson Arantes do Nascimento."]', '["Pelé","Pele","Edson Arantes do Nascimento"]', NULL);
