INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('futebol-052', 'en', 'Who or what is it?', 'Garrincha: He was born in Pau Grande, Rio de Janeiro. He was famous for dribbling on the right wing. He starred for Brazil at the 1962 World Cup. He was nicknamed the Joy of the People.', NULL, '["He was born in Pau Grande, Rio de Janeiro.","He was famous for dribbling on the right wing.","He starred for Brazil at the 1962 World Cup.","He was nicknamed the Joy of the People."]', '["Garrincha","Mane Garrincha"]', NULL);
