INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-051', 'pt-BR', 'Quem ou o que é?', 'Dandara: É um jogo de plataforma brasileiro. Foi criado pelo estúdio Long Hat House. Sua heroína se move saltando entre superfícies. Leva o nome de uma figura histórica ligada à resistência negra no Brasil.', NULL, '["É um jogo de plataforma brasileiro.","Foi criado pelo estúdio Long Hat House.","Sua heroína se move saltando entre superfícies.","Leva o nome de uma figura histórica ligada à resistência negra no Brasil."]', '["Dandara"]', NULL);
INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-051', 'en', 'Who or what is it?', 'Dandara: It is a Brazilian platform game. It was created by Long Hat House. Its heroine moves by jumping between surfaces. It is named after a historical figure associated with Black resistance in Brazil.', NULL, '["It is a Brazilian platform game.","It was created by Long Hat House.","Its heroine moves by jumping between surfaces.","It is named after a historical figure associated with Black resistance in Brazil."]', '["Dandara"]', NULL);
