INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-052', 'pt-BR', 'Quem ou o que é?', 'Lúcio: É um herói brasileiro de Overwatch. É associado ao Rio de Janeiro. Usa música para ajudar seus aliados. Move-se sobre patins e usa um amplificador sônico.', NULL, '["É um herói brasileiro de Overwatch.","É associado ao Rio de Janeiro.","Usa música para ajudar seus aliados.","Move-se sobre patins e usa um amplificador sônico."]', '["Lúcio","Lucio"]', NULL);
