INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-053', 'pt-BR', 'Quem ou o que é?', 'Chroma Squad: É um jogo do estúdio brasileiro Behold Studios. Mistura RPG tático e gestão. Seus protagonistas montam um programa de televisão. Sua estética homenageia equipes de heróis de séries sentai.', NULL, '["É um jogo do estúdio brasileiro Behold Studios.","Mistura RPG tático e gestão.","Seus protagonistas montam um programa de televisão.","Sua estética homenageia equipes de heróis de séries sentai."]', '["Chroma Squad"]', NULL);
INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-053', 'en', 'Who or what is it?', 'Chroma Squad: It is a game by Brazilian developer Behold Studios. It mixes tactical RPG combat and management. Its protagonists create a television show. Its style pays tribute to teams of sentai heroes.', NULL, '["It is a game by Brazilian developer Behold Studios.","It mixes tactical RPG combat and management.","Its protagonists create a television show.","Its style pays tribute to teams of sentai heroes."]', '["Chroma Squad"]', NULL);
