INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-054', 'pt-BR', 'Quem ou o que é?', 'Mônica: É uma personagem brasileira dos quadrinhos. Protagonizou jogos lançados pela Tectoy. Costuma usar vestido vermelho. Seu coelho de pelúcia se chama Sansão.', NULL, '["É uma personagem brasileira dos quadrinhos.","Protagonizou jogos lançados pela Tectoy.","Costuma usar vestido vermelho.","Seu coelho de pelúcia se chama Sansão."]', '["Mônica","Monica"]', NULL);
INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-054', 'en', 'Who or what is it?', 'Mônica: She is a Brazilian comics character. She starred in games released by Tectoy. She usually wears a red dress. Her stuffed rabbit is called Sansão.', NULL, '["She is a Brazilian comics character.","She starred in games released by Tectoy.","She usually wears a red dress.","Her stuffed rabbit is called Sansão."]', '["Mônica","Monica"]', NULL);
