INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-055', 'pt-BR', 'Quem ou o que é?', 'Minecraft: Usa um mundo formado por blocos. Tem modos como Sobrevivência e Criativo. O jogador pode minerar recursos e construir estruturas. Seus inimigos incluem creepers e endermen.', NULL, '["Usa um mundo formado por blocos.","Tem modos como Sobrevivência e Criativo.","O jogador pode minerar recursos e construir estruturas.","Seus inimigos incluem creepers e endermen."]', '["Minecraft"]', NULL);
INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-055', 'en', 'Who or what is it?', 'Minecraft: It uses a world made of blocks. It has Survival and Creative modes. Players can mine resources and build structures. Its enemies include creepers and endermen.', NULL, '["It uses a world made of blocks.","It has Survival and Creative modes.","Players can mine resources and build structures.","Its enemies include creepers and endermen."]', '["Minecraft"]', NULL);
