INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-056', 'pt-BR', 'Quem ou o que é?', 'Pac-Man: Surgiu nos fliperamas. Seu protagonista é amarelo. Há fantasmas chamados Blinky e Pinky. O herói come pastilhas em labirintos.', NULL, '["Surgiu nos fliperamas.","Seu protagonista é amarelo.","Há fantasmas chamados Blinky e Pinky.","O herói come pastilhas em labirintos."]', '["Pac-Man","Pac Man"]', NULL);
INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-056', 'en', 'Who or what is it?', 'Pac-Man: It began in arcades. Its protagonist is yellow. It features ghosts named Blinky and Pinky. The hero eats dots in mazes.', NULL, '["It began in arcades.","Its protagonist is yellow.","It features ghosts named Blinky and Pinky.","The hero eats dots in mazes."]', '["Pac-Man","Pac Man"]', NULL);
