INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-057', 'pt-BR', 'Quem ou o que é?', 'Tetris: Foi criado por Alexey Pajitnov. É um jogo de quebra-cabeça. As peças caem do alto da tela. Completar linhas horizontais faz com que elas desapareçam.', NULL, '["Foi criado por Alexey Pajitnov.","É um jogo de quebra-cabeça.","As peças caem do alto da tela.","Completar linhas horizontais faz com que elas desapareçam."]', '["Tetris"]', NULL);
INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-057', 'en', 'Who or what is it?', 'Tetris: It was created by Alexey Pajitnov. It is a puzzle game. Pieces fall from the top of the screen. Completing horizontal lines makes them disappear.', NULL, '["It was created by Alexey Pajitnov.","It is a puzzle game.","Pieces fall from the top of the screen.","Completing horizontal lines makes them disappear."]', '["Tetris"]', NULL);
