INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-058', 'pt-BR', 'Quem ou o que é?', 'Donkey Kong: É um personagem da Nintendo. Tem forte ligação com barris e bananas. É um grande gorila. Seu nome aparece em uma série com o subtítulo Country.', NULL, '["É um personagem da Nintendo.","Tem forte ligação com barris e bananas.","É um grande gorila.","Seu nome aparece em uma série com o subtítulo Country."]', '["Donkey Kong"]', NULL);
INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-058', 'en', 'Who or what is it?', 'Donkey Kong: He is a Nintendo character. He is closely associated with barrels and bananas. He is a large gorilla. His name appears in a series with the subtitle Country.', NULL, '["He is a Nintendo character.","He is closely associated with barrels and bananas.","He is a large gorilla.","His name appears in a series with the subtitle Country."]', '["Donkey Kong"]', NULL);
