INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-059', 'pt-BR', 'Quem ou o que é?', 'Yoshi: É um aliado de Mario. Sua versão mais conhecida é verde. Usa uma língua comprida e pode produzir ovos. É um dinossauro que Mario pode montar.', NULL, '["É um aliado de Mario.","Sua versão mais conhecida é verde.","Usa uma língua comprida e pode produzir ovos.","É um dinossauro que Mario pode montar."]', '["Yoshi"]', NULL);
INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-059', 'en', 'Who or what is it?', 'Yoshi: He is an ally of Mario. His best-known version is green. He uses a long tongue and can produce eggs. He is a dinosaur Mario can ride.', NULL, '["He is an ally of Mario.","His best-known version is green.","He uses a long tongue and can produce eggs.","He is a dinosaur Mario can ride."]', '["Yoshi"]', NULL);
