INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-062', 'pt-BR', 'Quem ou o que é?', 'The Sims: É uma série de simulação de vida. Permite construir e mobiliar casas. Os personagens têm necessidades e relações sociais. Um cristal chamado Plumbob aparece sobre o personagem selecionado.', NULL, '["É uma série de simulação de vida.","Permite construir e mobiliar casas.","Os personagens têm necessidades e relações sociais.","Um cristal chamado Plumbob aparece sobre o personagem selecionado."]', '["The Sims","Sims"]', NULL);
