INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-063', 'pt-BR', 'Quem ou o que é?', 'Stardew Valley: Foi criado por Eric Barone, conhecido como ConcernedApe. Combina agricultura, pesca e mineração. O jogador convive com os moradores da Vila Pelicanos. A aventura começa em uma fazenda herdada do avô.', NULL, '["Foi criado por Eric Barone, conhecido como ConcernedApe.","Combina agricultura, pesca e mineração.","O jogador convive com os moradores da Vila Pelicanos.","A aventura começa em uma fazenda herdada do avô."]', '["Stardew Valley"]', NULL);
INSERT INTO quiz_question_texts (question_id, language, prompt, explanation, options_json, clues_json, answers_json, unit) VALUES ('videogames-063', 'en', 'Who or what is it?', 'Stardew Valley: It was created by Eric Barone, known as ConcernedApe. It combines farming, fishing and mining. Players meet the residents of Pelican Town. The adventure starts on a farm inherited from a grandfather.', NULL, '["It was created by Eric Barone, known as ConcernedApe.","It combines farming, fishing and mining.","Players meet the residents of Pelican Town.","The adventure starts on a farm inherited from a grandfather."]', '["Stardew Valley"]', NULL);
